<?php
require __DIR__.'/includes/session.php'; require __DIR__.'/includes/admin-layout.php'; require __DIR__.'/includes/challenges.php';
$account=require_account(true); $error=''; $rows=[]; $edit=null;
try { $db=spellstorm_database(); if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $id=field('id'); $action=field('action'); if($id!==''&&!preg_match('/\A[0-9a-f-]{36}\z/i',$id)) throw new InvalidArgumentException('Invalid challenge.');
if($action==='save') save_challenge($db,$id,field('title'),field('description'),field('type'),(int)field('target'));
elseif($action==='delete'&&$id!=='') { $s=$db->prepare('DELETE FROM public.challenges WHERE id=? AND tier IS NULL AND NOT EXISTS (SELECT 1 FROM public.player_achievements WHERE challenge_id=challenges.id)'); $s->execute([$id]); if(!$s->rowCount()) throw new InvalidArgumentException('Core achievements cannot be deleted; earned optional challenges must be archived.'); }
elseif(in_array($action,['archive','activate'],true)&&$id!=='') { $s=$db->prepare('UPDATE public.challenges SET active='.($action==='activate'?'true':'false').' WHERE id=? AND tier IS NULL'); $s->execute([$id]); if(!$s->rowCount()) throw new InvalidArgumentException('Core achievements cannot be archived.'); }
else throw new InvalidArgumentException('Invalid action.'); redirect_to('admin-challenges.php?saved=1'); } } catch(InvalidArgumentException $e){$error=$e->getMessage();} catch(Throwable $e){$error='Unable to manage challenges.';}
try {$rows=challenge_list(spellstorm_database()); foreach($rows as $row) if($row['id']===($_GET['edit']??null)) $edit=$row;} catch(Throwable $e){$error='Challenge service unavailable.';}
admin_header('Challenge Management','challenges',$account); ?>
<p>Set gameplay goals and award badges for completed runs.</p><?php if($error): ?><p class="error" role="alert"><?=escape($error)?></p><?php elseif(isset($_GET['saved'])): ?><p role="status">Changes saved.</p><?php endif; ?>
<section class="admin-panel"><h2><?=$edit?'Edit challenge':'Create challenge'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=escape($edit['id']??'')?>"><label>Title<input class="form-control" name="title" maxlength="100" required value="<?=escape($edit['title']??'')?>"></label><label>Description<textarea class="form-control" name="description" maxlength="1000" required><?=escape($edit['description']??'')?></textarea></label><label>Condition<select class="form-select" name="type"><?php foreach(['finish'=>'Finish a run','win'=>'Win a run','circle'=>'Reach circle','score'=>'Minimum score'] as $key=>$name): ?><option value="<?=$key?>" <?=($edit['condition_type']??'')===$key?'selected':''?>><?=escape($name)?></option><?php endforeach; ?></select></label><label>Target (1 for finish/win)<input class="form-control" name="target" type="number" min="1" required value="<?=(int)($edit['target']??1)?>"></label><?php if($edit): ?><p>Existing conditions are fixed to preserve earned badges.</p><?php endif; ?><button class="btn btn-primary mt-3">Save challenge</button> <a href="admin-challenges.php">Cancel</a></form></section>
<section class="admin-panel"><h2>Challenges</h2><?php foreach($rows as $row): ?><article class="guide-item"><strong><?=escape($row['title'])?></strong> <span class="badge bg-secondary"><?=escape([1=>'Initiate',2=>'Veteran',3=>'Hardcore'][$row['tier']]??'Optional')?></span> · <?=escape($row['condition_type'])?> <?=(int)$row['target']?> · <?=(int)$row['earned']?> earned · <?=$row['active']?'Active':'Archived'?><p><?=escape($row['description'])?></p><a href="?edit=<?=escape($row['id'])?>">Edit</a> <?php if($row['tier']===null): ?><form class="d-inline" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=escape($row['id'])?>"><button class="btn btn-sm btn-outline-light" name="action" value="<?=$row['active']?'archive':'activate'?>"><?=$row['active']?'Archive':'Activate'?></button><?php if(!(int)$row['earned']): ?> <button class="btn btn-sm btn-outline-danger" name="action" value="delete" onclick="return confirm('Delete this challenge?')">Delete</button><?php endif; ?></form><?php else: ?> <small>Core tier achievement</small><?php endif; ?></article><?php endforeach; ?></section><?php admin_footer(); ?>
